@push('styles')
<style>
.bm-shell{max-width:1280px;margin:auto}.bm-hero,.bm-card{background:#fff;border:1px solid #e2e9f0;border-radius:.85rem;box-shadow:0 8px 22px rgba(30,65,95,.06)}.bm-hero{padding:1.5rem;display:flex;gap:1rem;align-items:center;justify-content:space-between;animation:bm-enter .35s ease both}.bm-kicker{display:block;color:#188ae2;font-size:.73rem;font-weight:700;letter-spacing:.08em;text-transform:uppercase}.bm-hero h1{margin:.15rem 0;font-size:1.6rem}.bm-hero p{margin:0;color:#64748b}.bm-logo{width:48px}.bm-metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:1rem;margin:1rem 0}.bm-metric{padding:1.1rem;background:#f7fbff;border:1px solid #e2e9f0;border-radius:.75rem;animation:bm-enter .4s ease both}.bm-metric:nth-child(2){animation-delay:.06s}.bm-metric:nth-child(3){animation-delay:.12s}.bm-metric strong{display:block;font-size:1.65rem;color:#1f3d5a}.bm-card{padding:1.25rem;margin-top:1rem}.bm-toolbar{display:flex;gap:.75rem;align-items:center;justify-content:space-between;flex-wrap:wrap}.bm-table{margin:1rem 0 0}.bm-table tbody tr{transition:.18s ease}.bm-table tbody tr:hover{transform:translateY(-2px);box-shadow:0 5px 12px rgba(24,138,226,.09)}.bm-status{font-size:.75rem;border-radius:99px;padding:.35rem .6rem;font-weight:700;background:#eef6fd;color:#188ae2}.bm-status.ok{background:#eafaf4;color:#17815c}.bm-status.warn{background:#fff6df;color:#a26a00}.bm-status.danger{background:#fff0f0;color:#c24141}.bm-flow{display:flex;gap:.5rem;flex-wrap:wrap;margin-top:.7rem}.bm-flow span{padding:.4rem .65rem;background:#f5f5f5;border-radius:99px;font-size:.8rem}.bm-flow .is-current{background:#188ae2;color:#fff}.bm-form-section{padding:1rem;border:1px solid #e2e9f0;border-radius:.75rem;margin:1rem 0;background:#fbfdff}.bm-form-section h2{font-size:1.05rem}.bm-form-section .select2-container{width:100%!important}.bm-form-section .select2-container--bootstrap-5 .select2-selection{min-height:38px;border-color:#ced4da;border-radius:.375rem}.bm-form-section .select2-container--bootstrap-5.select2-container--focus .select2-selection{border-color:#188ae2;box-shadow:0 0 0 .2rem rgba(24,138,226,.16)}.select2-container--open{z-index:1085}.select2-container--bootstrap-5 .select2-dropdown{border-color:#d6e4ef;box-shadow:0 10px 24px rgba(30,65,95,.14)}.select2-container--bootstrap-5 .select2-results__option--highlighted.select2-results__option--selectable{background:#188ae2}.bm-detail-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:.8rem}.bm-fact{background:#f7fbff;border-radius:.65rem;padding:.8rem}.bm-fact span{display:block;font-size:.75rem;color:#64748b}.bm-fact strong{display:block;margin-top:.2rem}.bm-timeline{border-left:2px solid #dcecf8;margin:.8rem 0;padding-left:1rem}.bm-timeline-item{position:relative;padding:0 0 1rem}.bm-timeline-item:before{content:'';position:absolute;left:-1.42rem;top:.2rem;width:.7rem;height:.7rem;border-radius:50%;background:#188ae2}.bm-save{position:relative}.bm-save:disabled:after{content:'';display:inline-block;width:.8rem;height:.8rem;border:2px solid #fff;border-right-color:transparent;border-radius:50%;margin-left:.5rem;animation:bm-spin .7s linear infinite}@keyframes bm-enter{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}@keyframes bm-logo{to{transform:rotate(360deg)}}@keyframes bm-spin{to{transform:rotate(360deg)}}@media(max-width:640px){.bm-hero{align-items:flex-start}.bm-metrics{grid-template-columns:1fr}.bm-hero .btn{width:100%}}@media(prefers-reduced-motion:reduce){.bm-hero,.bm-metric,.bm-table tbody tr,.bm-logo,.bm-save:disabled:after{animation:none;transition:none}}
.bm-section-help{margin:-.2rem 0 .9rem;color:#64748b;font-size:.88rem}.bm-budget-preview{margin-top:1rem;padding:1rem;background:#f7fbff;border:1px solid #dbeaf6;border-radius:.75rem;transition:box-shadow .18s ease,transform .18s ease}.bm-budget-preview.is-ready{animation:bm-enter .24s ease both}.bm-budget-preview.is-loading{opacity:.72}.bm-budget-preview.is-warning{border-color:#f0bd53;background:#fffaf0}.bm-budget-preview-head{display:flex;align-items:start;justify-content:space-between;gap:1rem}.bm-budget-preview h3{margin:.1rem 0 0;font-size:1rem}.bm-preview-state{font-size:.78rem;color:#64748b;text-align:right}.bm-preview-values{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:.65rem;margin-top:.8rem}.bm-preview-values>div{padding:.65rem .7rem;background:#fff;border:1px solid #e2e9f0;border-radius:.6rem}.bm-preview-values span{display:block;font-size:.72rem;color:#64748b}.bm-preview-values strong{display:block;margin-top:.18rem;color:#1f3d5a;font-size:1rem}.bm-preview-projected{border-color:#bde8d5!important;background:#f1fcf7!important}.bm-preview-projected strong{color:#17815c}.bm-budget-preview.is-warning .bm-preview-projected{border-color:#f0bd53!important;background:#fff4d6!important}.bm-budget-preview.is-warning .bm-preview-projected strong{color:#a26a00}.bm-preview-note{margin-top:.7rem;color:#64748b;font-size:.78rem}@media(max-width:640px){.bm-preview-values{grid-template-columns:repeat(2,minmax(0,1fr))}.bm-budget-preview-head{display:block}.bm-preview-state{display:block;text-align:left;margin-top:.4rem}}@media(prefers-reduced-motion:reduce){.bm-budget-preview{animation:none!important;transition:none!important}}
.bm-cedula-option{display:flex;align-items:center;justify-content:space-between;gap:.5rem;width:100%}.bm-cedula-name{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.bm-cedula-badge{flex-shrink:0;font-variant-numeric:tabular-nums}
.bm-type-options{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:.75rem;margin-top:.25rem}.bm-type-options.bm-invalid .bm-type-card{border-color:var(--bs-danger)}.bm-type-option{position:relative;margin:0;cursor:pointer}.bm-type-option input{position:absolute;opacity:0;width:1px;height:1px}.bm-type-card{display:grid;grid-template-columns:auto 1fr;column-gap:.65rem;row-gap:.15rem;align-items:center;height:100%;padding:.85rem 1rem;background:#fff;border:1px solid #d6e2ec;border-radius:.75rem;transition:border-color .15s ease,background-color .15s ease,box-shadow .15s ease}.bm-type-card i{grid-row:span 2;font-size:1.5rem;color:#64748b}.bm-type-card strong{color:#1f3d5a}.bm-type-card small{color:#64748b;line-height:1.35}.bm-type-option:hover .bm-type-card{border-color:#9cc9ee}.bm-type-option input:checked+.bm-type-card{border-color:#188ae2;background:#f2f8fe;box-shadow:inset 0 0 0 1px #188ae2}.bm-type-option input:checked+.bm-type-card i{color:#188ae2}.bm-type-option input:focus-visible+.bm-type-card{outline:2px solid #188ae2;outline-offset:2px}
.bm-line-title{font-size:.95rem;font-weight:700;color:#1f3d5a;margin:0 0 .15rem}.bm-attachments{font-size:.85rem;color:#475569}.bm-attachments ul{list-style:none;padding:0}.bm-summary{padding:1rem 1.1rem;border:1px solid #bcdaf3;border-radius:.75rem;background:#f2f8fe;margin-top:1rem}.bm-summary h2{font-size:1.05rem;margin-bottom:.35rem}.bm-summary p{color:#334155;max-width:75ch}.bm-summary strong{color:#1f3d5a}
@media(max-width:768px){.bm-type-options{grid-template-columns:1fr}}@media(prefers-reduced-motion:reduce){.bm-type-card{transition:none}}
.bm-card>h2{font-size:1.05rem;margin-bottom:.75rem;color:#1f3d5a}.bm-hero-meta{margin:0 0 .1rem!important;font-size:.85rem}.bm-hero .bm-status{display:inline-block;margin-top:.35rem}
.bm-steps{display:flex;flex-wrap:wrap;gap:.4rem;list-style:none;padding:0;margin:.8rem 0 0}.bm-steps li{display:inline-flex;align-items:center;gap:.35rem;padding:.35rem .7rem;border-radius:99px;font-size:.8rem;background:#f1f5f9;color:#64748b}.bm-steps li.is-done{background:#eafaf4;color:#17815c}.bm-steps li.is-current{background:#188ae2;color:#fff;font-weight:600}.bm-steps li.is-returned{background:#fff6df;color:#a26a00;font-weight:600}.bm-steps li.is-failed{background:#fff0f0;color:#c24141;font-weight:600}
.bm-owner{border-color:#bcdaf3;background:#f2f8fe}.bm-owner-success{border-color:#bde8d5;background:#f1fcf7}.bm-owner-warning{border-color:#f0d58c;background:#fffaf0}.bm-owner-danger{border-color:#f3c4c4;background:#fff7f7}.bm-owner h2{margin-bottom:.35rem}.bm-owner-verb{margin:0 0 .5rem;color:#475569;font-size:.9rem}.bm-people{display:flex;flex-wrap:wrap;gap:.6rem;list-style:none;padding:0;margin:0}.bm-people li{display:flex;gap:.7rem;align-items:flex-start;min-width:240px;padding:.7rem .85rem;background:#fff;border:1px solid #e2e9f0;border-radius:.65rem}.bm-avatar{flex-shrink:0;display:grid;place-items:center;width:2.25rem;height:2.25rem;border-radius:50%;background:#e3f0fb;color:#188ae2;font-weight:700}.bm-person-role{font-size:.85rem;color:#475569}.bm-owner-next{margin-top:.75rem;color:#475569;font-size:.9rem}.bm-reason{margin:.75rem 0 0;padding:.7rem .9rem;background:#fff;border:1px solid #e2e9f0;border-radius:.65rem}.bm-reason p{color:#1f3d5a}
.bm-action{border-color:#188ae2}.bm-action h2{margin-bottom:.25rem}.bm-decision summary{list-style:none}.bm-decision summary::-webkit-details-marker{display:none}.bm-decision[open] summary{margin-bottom:0}.bm-decision form{min-width:min(420px,80vw)}
.bm-subtitle{font-size:.85rem;font-weight:700;color:#475569;margin:1.1rem 0 .3rem}.bm-prose{max-width:75ch;white-space:pre-line}.bm-files{list-style:none;padding:0;margin:0}.bm-files li{padding:.25rem 0}.bm-amount{font-variant-numeric:tabular-nums;white-space:nowrap;font-weight:600}
.bm-invalid.select2 .select2-selection,.bm-invalid.input-group .form-control{border-color:var(--bs-danger)!important}
</style>
@endpush
